import * as React from "react"
import { CalendarIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Calendar } from "@/components/ui/calendar"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover"

// Small natural-language parser (today, tomorrow, in N days/weeks/months,
// next <weekday>), falling back to Date.parse for explicit dates.
function parseDate(input: string): Date | null {
  const text = input.trim().toLowerCase()
  const base = new Date()
  base.setHours(0, 0, 0, 0)
  const add = (days: number) => new Date(base.getFullYear(), base.getMonth(), base.getDate() + days)
  if (text === "today") return base
  if (text === "tomorrow") return add(1)
  const words: Record<string, number> = { a: 1, an: 1, one: 1, two: 2, three: 3, four: 4, five: 5 }
  const rel = text.match(/^in (\d+|a|an|one|two|three|four|five) (day|week|month)s?$/)
  if (rel) {
    const n = words[rel[1]!] ?? Number(rel[1])
    if (rel[2] === "day") return add(n)
    if (rel[2] === "week") return add(n * 7)
    return new Date(base.getFullYear(), base.getMonth() + n, base.getDate())
  }
  const weekdays = ["sunday", "monday", "tuesday", "wednesday", "thursday", "friday", "saturday"]
  const next = text.match(/^next (\w+)$/)
  if (next && weekdays.includes(next[1]!)) {
    const diff = (weekdays.indexOf(next[1]!) - base.getDay() + 7) % 7 || 7
    return add(diff)
  }
  if (next && next[1] === "week") return add(7)
  const parsed = new Date(input)
  return Number.isNaN(parsed.getTime()) ? null : parsed
}

function formatDate(date: Date | undefined) {
  if (!date) {
    return ""
  }

  return date.toLocaleDateString("en-US", {
    day: "2-digit",
    month: "long",
    year: "numeric",
  })
}

function Calendar29() {
  const [open, setOpen] = React.useState(false)
  const [value, setValue] = React.useState("In 2 days")
  const [date, setDate] = React.useState<Date | undefined>(
    parseDate(value) || undefined
  )
  const [month, setMonth] = React.useState<Date | undefined>(date)

  return (
    <div className="flex flex-col gap-3">
      <Label htmlFor="date" className="px-1">
        Schedule Date
      </Label>
      <div className="relative flex gap-2">
        <Input
          id="date"
          value={value}
          placeholder="Tomorrow or next week"
          className="bg-background pr-10"
          onChange={(e) => {
            setValue(e.target.value)
            const date = parseDate(e.target.value)
            if (date) {
              setDate(date)
              setMonth(date)
            }
          }}
          onKeyDown={(e) => {
            if (e.key === "ArrowDown") {
              e.preventDefault()
              setOpen(true)
            }
          }}
        />
        <Popover open={open} onOpenChange={setOpen}>
          <PopoverTrigger
          render={<Button
              id="date-picker"
              variant="ghost"
              className="absolute top-1/2 right-2 size-6 -translate-y-1/2" />}
        >
          <CalendarIcon className="size-3.5" />
              <span className="sr-only">Select date</span>
        </PopoverTrigger>
          <PopoverContent className="w-auto overflow-hidden p-0" align="end">
            <Calendar
              mode="single"
              selected={date}
              captionLayout="dropdown"
              month={month}
              onMonthChange={setMonth}
              onSelect={(date) => {
                setDate(date)
                setValue(formatDate(date))
                setOpen(false)
              }}
            />
          </PopoverContent>
        </Popover>
      </div>
      <div className="text-muted-foreground px-1 text-sm">
        Your post will be published on{" "}
        <span className="font-medium">{formatDate(date)}</span>.
      </div>
    </div>
  )
}

export default function Page() {
  return (
    <div className="flex min-h-svh items-center justify-center p-6">
      <Calendar29 />
    </div>
  )
}
